typedef unsigned char uint8;
typedef float rational_t;
typedef float vm_num_t;

extern "C" int strlen(const char*);

class stringx;
class string_buf
{
  friend class stringx;
  friend stringx operator+(const stringx&, const stringx&);
  friend stringx operator+(const char*, const stringx&);
  friend stringx operator+(const stringx&, const char*);
  long long* data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
};

class stringx
{
  string_buf* my_buf;
public:
  stringx();
  stringx(const stringx&);
  ~stringx();
  void make_room(int);
  void append(const stringx&);
  void append(const char*, int);
  friend stringx operator+(const stringx&, const stringx&);
  friend stringx operator+(const char*, const stringx&);
  friend stringx operator+(const stringx&, const char*);
};

inline stringx operator+(const stringx& lhs, const stringx& rhs)
{
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const char* lhs, const stringx& rhs)
{
  stringx foo;
  int len = strlen(lhs);
  foo.make_room(len + rhs.my_buf->char_length);
  foo.append(lhs, len);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const stringx& lhs, const char* rhs)
{
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

class script_object
{
public:
  class instance
  {
    stringx name;
  public:
    const stringx& get_name() const { return name; }
  };
};

class vm_executable
{
  stringx name;
  stringx fullname;
public:
  const stringx& get_fullname() const { return fullname; }
};

class vm_thread
{
  script_object::instance* inst;
  const vm_executable* ex;
public:
  script_object::instance* get_instance() const { return inst; }
  const vm_executable* get_executable() const { return ex; }
};

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
public:
  char* get_SP() const { return SP; }
  vm_thread* get_thread() const { return my_thread; }
  void pop(int n) { SP -= n; }
  bool push(const char*, int);
};

void error(const stringx&);

class beam
{
public:
  unsigned short add_alpha_effect(uint8, uint8, rational_t, rational_t,
                                  rational_t, bool);
};
typedef beam* vm_beam_t;

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

class slf_beam_add_alpha_effect_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vm_beam_t me;

    vm_num_t start_a;
    vm_num_t end_a;

    vm_num_t duration;
    vm_num_t delay;
    vm_num_t loop_delay;
    vm_num_t invert;
  };

  virtual bool operator()( vm_stack& stack, entry_t entry );
};

bool slf_beam_add_alpha_effect_t::operator()( vm_stack& stack, entry_t entry )
{
  stack.pop(sizeof(parms_t));
  parms_t* parms = (parms_t*)stack.get_SP();
  rational_t result = parms->me->add_alpha_effect((uint8)parms->start_a, (uint8)parms->end_a, parms->duration, parms->delay, parms->loop_delay, (bool)parms->invert);
  if (!stack.push((char*)&result,sizeof(result)) )
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() );
  return true;
}
